"""Writes results.json, report.md and the plots. Generated files: do not edit by hand."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402

from .models import MODEL_IDS  # noqa: E402

NAMES = {
    "B0": "Global average rating",
    "B1": "Questionnaire and trait match (derived questionnaire)",
    "B2": "Taste vector (embeddings)",
    "B3": "Item-based collaborative filtering",
    "B4": "Hybrid of B2 and B3",
    "B2-traits": "Taste vector (traits only)",
    "B4+prior": "Hybrid with questionnaire prior",
}


def rounded(value: Any, places: int = 6) -> Any:
    """Rounds every float, so results compare equal across runs and machines."""
    if isinstance(value, float):
        return round(value, places)
    if isinstance(value, dict):
        return {k: rounded(v, places) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [rounded(v, places) for v in value]
    if hasattr(value, "tolist"):
        return rounded(value.tolist(), places)
    return value


def _fmt(m: dict[str, Any], places: int = 3) -> str:
    if m["value"] is None:
        return "n/a"
    return f"{m['value']:.{places}f} [{m['low']:.{places}f}, {m['high']:.{places}f}]"


def _signed(m: dict[str, Any], places: int = 3) -> str:
    if m["value"] is None:
        return "n/a"
    return f"{m['value']:+.{places}f} [{m['low']:+.{places}f}, {m['high']:+.{places}f}]"


def write(results: dict[str, Any], out_dir: Path) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    data = rounded(results)
    (out_dir / "results.json").write_text(json.dumps(data, indent=2) + "\n", "utf-8", newline="\n")
    _plot_learning_curve(data, out_dir / "learning-curve.png")
    _plot_calibration(data, out_dir / "calibration.png")
    (out_dir / "report.md").write_text(_markdown(data), "utf-8", newline="\n")


def _markdown(r: dict[str, Any]) -> str:
    d = r["data"]
    p = r["provenance"]["params"]
    pct = int(round(p["metrics"]["interval"] * 100))
    k = p["metrics"]["ndcg_k"]
    lines = [
        "# Offline evaluation: results",
        "",
        "Generated by `pnpm eval` (EVAL-1). Do not edit by hand; the method is in `eval/README.md`.",
        "",
        "## Data",
        "",
        f"- Books: {d['books']} (the {p['data']['top_editions']} most-rated editions in the dev catalog, one per work); "
        f"{d['booksWithEmbedding']} with an embedding, {d['booksWithTraits']} with traits.",
        f"- Readers with at least {p['data']['min_ratings']} ratings among them: {d['qualifyingReaders']}; "
        f"{d['evaluatedReaders']} evaluated (drawn with seed {p['split']['seed']}).",
        f"- Population (trains B0 and B3 only): {d['populationReaders']} other readers, {d['populationRatings']} ratings.",
        f"- Evaluated ratings: {d['ratings']['train']} profile, {d['ratings']['validation']} validation, "
        f"{d['ratings']['test']} test (per reader {int(p['split']['test_fraction'] * 100)}% test, "
        f"{int(p['split']['validation_fraction'] * 100)}% validation). Median profile: {d['medianProfileSize']:g} books.",
        f"- Test books with an embedding: {d['testBooksWithEmbedding'] * 100:.1f}%; with traits: {d['testBooksWithTraits'] * 100:.1f}%.",
        f"- Snapshot checksum: `{r['provenance']['snapshot']['checksum'][:16]}`; harness checksum: `{r['provenance']['harnessChecksum'][:16]}`.",
        "",
        "## Results",
        "",
        f"Mean over readers with a {pct}% bootstrap interval over readers ({p['metrics']['bootstrap_samples']} resamples). "
        f"Higher is better for Spearman and NDCG@{k}; lower is better for MAE (stars).",
        "",
        f"| Model | Split | Spearman | NDCG@{k} | MAE | Readers |",
        "|---|---|---|---|---|---|",
    ]
    for m in MODEL_IDS:
        for split in ("validation", "test"):
            s = r["models"][m][split]
            lines.append(
                f"| {m} {NAMES[m]} | {split} | {_fmt(s['spearman'])} | {_fmt(s['ndcg'])} | {_fmt(s['mae'])} | "
                f"{s['spearman']['readers']} / {s['ndcg']['readers']} / {s['mae']['readers']} |"
            )
    sel = r["selection"]
    lines += [
        "",
        "Readers are counted per metric (Spearman / NDCG / MAE): Spearman leaves out readers whose held-out "
        "ratings are all equal, NDCG readers whose held-out ratings are all 1.",
        "",
        f"**Shipped model: {sel['shipped']}** ({sel['metric']}). Validation ranking: "
        + ", ".join(f"{x['model']} ({x['spearman']:.3f})" for x in sel["validationRanking"])
        + ".",
        "",
        "### Difference from B0 on test (paired over readers)",
        "",
        f"| Model | Spearman | NDCG@{k} | MAE |",
        "|---|---|---|---|",
    ]
    for m, diff in r["differenceFromB0OnTest"].items():
        lines.append(f"| {m} | {_signed(diff['spearman'])} | {_signed(diff['ndcg'])} | {_signed(diff['mae'])} |")
    lines += [
        "",
        "An interval that excludes 0 is a difference this sample supports. For MAE, negative means fewer stars of error than B0.",
        "",
        "## Ablations (test)",
        "",
        f"| Variant | What it uses | Spearman | NDCG@{k} | MAE |",
        "|---|---|---|---|---|",
    ]
    for m, desc in r["ablations"]["description"].items():
        s = r["ablations"]["test"][m]
        lines.append(f"| {m} | {desc} | {_fmt(s['spearman'])} | {_fmt(s['ndcg'])} | {_fmt(s['mae'])} |")
    lines += [
        "",
        "## Learning curve (test, mean per-reader Spearman)",
        "",
        "Each point limits the profile to k of the reader's profile ratings (drawn with the seed) and predicts the same test books. "
        "Only readers with at least k profile ratings take part, so the reader count falls as k grows.",
        "",
        "| Profile size | Readers | " + " | ".join(MODEL_IDS) + " |",
        "|---|---|" + "---|" * len(MODEL_IDS),
    ]
    for point in r["learningCurve"]["points"]:
        cells = [_fmt(point["models"][m]["spearman"]) if point["models"] else "n/a" for m in MODEL_IDS]
        lines.append(f"| {point['profileSize']} | {point['readers']} | " + " | ".join(cells) + " |")
    cal = r["calibration"]
    lines += [
        "",
        "![Learning curve](learning-curve.png)",
        "",
        f"## Calibration ({cal['model']}, test)",
        "",
        f"Predicted scores binned by {cal['binWidth']} stars and compared with the actual ratings. "
        f"Expected calibration error: {cal['expectedCalibrationError']:.3f} stars.",
        "",
        "| Predicted | Books | Mean predicted | Mean actual |",
        "|---|---|---|---|",
    ]
    for b in cal["bins"]:
        if b["count"]:
            lines.append(f"| {b['from']:.1f} to {b['to']:.1f} | {b['count']} | {b['meanPredicted']:.2f} | {b['meanActual']:.2f} |")
    lines += [
        "",
        "![Calibration](calibration.png)",
        "",
        "## Fitted coefficients (validation split)",
        "",
        "```json",
        json.dumps(r["tuned"], indent=2),
        "```",
        "",
    ]
    return "\n".join(lines)


def _plot_learning_curve(r: dict[str, Any], path: Path) -> None:
    fig, ax = plt.subplots(figsize=(7, 4.2), dpi=120)
    points = [p for p in r["learningCurve"]["points"] if p["models"]]
    sizes = [p["profileSize"] for p in points]
    for m in MODEL_IDS:
        values = [p["models"][m]["spearman"] for p in points]
        y = [v["value"] for v in values]
        err = [[v["value"] - v["low"] for v in values], [v["high"] - v["value"] for v in values]]
        ax.errorbar(sizes, y, yerr=err, marker="o", capsize=3, label=f"{m}")
    ax.set_xscale("log", base=2)
    ax.set_xticks(sizes, [str(s) for s in sizes])
    ax.set_xlabel("Rated books in the profile")
    ax.set_ylabel("Mean per-reader Spearman (test)")
    ax.set_title("Learning curve")
    ax.grid(alpha=0.3)
    ax.legend(ncols=5, fontsize=8, loc="lower right")
    fig.tight_layout()
    fig.savefig(path, metadata={"Software": None})
    plt.close(fig)


def _plot_calibration(r: dict[str, Any], path: Path) -> None:
    cal = r["calibration"]
    bins = [b for b in cal["bins"] if b["count"]]
    fig, ax = plt.subplots(figsize=(4.8, 4.8), dpi=120)
    ax.plot([1, 5], [1, 5], linestyle="--", color="grey", label="Perfect calibration")
    ax.plot(
        [b["meanPredicted"] for b in bins],
        [b["meanActual"] for b in bins],
        marker="o",
        label=f"{cal['model']}",
    )
    for b in bins:
        ax.annotate(str(b["count"]), (b["meanPredicted"], b["meanActual"]), fontsize=7, xytext=(4, -10), textcoords="offset points")
    ax.set_xlim(1, 5)
    ax.set_ylim(1, 5)
    ax.set_xlabel("Mean predicted score")
    ax.set_ylabel("Mean actual rating")
    ax.set_title(f"Calibration ({cal['model']}, test)")
    ax.grid(alpha=0.3)
    ax.legend(fontsize=8, loc="upper left")
    fig.tight_layout()
    fig.savefig(path, metadata={"Software": None})
    plt.close(fig)
